const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=new Set(read('fieldnotes-saved',[]).filter(id=>IDEAS.some(i=>i.id===id))),notes=read('fieldnotes-notes',{});
if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};
let view='explore',category='All',toastTimer;
function persist(){try{localStorage.setItem('fieldnotes-saved',JSON.stringify([...saved]));localStorage.setItem('fieldnotes-notes',JSON.stringify(notes));storageOK=true;return true}catch{storageOK=false;toast('Browser storage is unavailable. Export your notes to keep them.');return false}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
const LEVELS=['concept','attention','repeated-pain','costly-workaround','existing-spend','paid-pilot','retention'];
const LEVEL_NAMES={concept:'Concept only',attention:'Attention','repeated-pain':'Repeated pain','costly-workaround':'Costly workaround','existing-spend':'Existing spend','paid-pilot':'Paid pilot',retention:'Retention',context:'Context only'};
const rank=i=>LEVELS.indexOf(i.level||'concept');
function matchEvidence(i){const v=$('#evidence').value;if(v==='all')return true;if(v==='researched')return!!i.evidenceLog?.length;if(v==='concept')return!i.evidenceLog?.length;return rank(i)>=LEVELS.indexOf(v)}
const isRecent=i=>i.reviewedAt&&Date.now()-Date.parse(i.reviewedAt)<=7*86400000;
function matchVerdict(i){const v=$('#verdict').value;return v==='all'||(v==='none'?!i.verdict:i.verdict===v)}
const bookmarkIcon='<svg width="16" height="19" viewBox="0 0 16 20" fill="none" aria-hidden="true"><path d="M3 2h10v16l-5-3-5 3V2Z" stroke="currentColor" stroke-width="1.5"/></svg>';
function updateNav(){$('#saved-count').textContent=saved.size;$('#browse').classList.toggle('active',view==='explore');$('#saved').classList.toggle('active',view==='saved')}
function render(){updateNav();const query=$('#search').value.trim().toLowerCase();let rows=IDEAS.filter(i=>(view!=='saved'||saved.has(i.id))&&(category==='All'||i.category===category)&&($('#model').value==='all'||i.model===$('#model').value)&&matchEvidence(i)&&matchVerdict(i)&&[i.name,i.title,i.summary,i.buyer,i.category].join(' ').toLowerCase().includes(query));if($('#sort').value==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));if($('#sort').value==='evidence')rows.sort((a,b)=>rank(b)-rank(a));if($('#sort').value==='recent')rows.sort((a,b)=>(b.reviewedAt||'').localeCompare(a.reviewedAt||''));const recent=IDEAS.filter(isRecent).sort((a,b)=>b.reviewedAt.localeCompare(a.reviewedAt));$('.recent').hidden=view==='saved'||!recent.length;$('#recent-ideas').innerHTML=recent.map(i=>`<li><button class="recent-title" data-open="${i.id}">${esc(i.title)}</button><span>${esc(i.verdict||'')} · ${LEVEL_NAMES[i.level||'concept']} · ${esc(i.reviewedAt)}</span></li>`).join('');$('#list-title').textContent=view==='saved'?'Your shortlist':'The idea collection';$('#result-count').textContent=`${rows.length} ${rows.length===1?'idea':'ideas'}`;$('.intro').hidden=view==='saved';$('.featured').hidden=view==='saved';$('#categories').innerHTML=['All',...new Set(IDEAS.map(i=>i.category))].map(c=>`<button data-category="${esc(c)}" class="${category===c?'selected':''}" aria-pressed="${category===c}">${esc(c)}</button>`).join('');$('#ideas').innerHTML=rows.length?rows.map((i,n)=>`<article class="idea-row"><span class="idea-index">${String(n+1).padStart(2,'0')}</span><div><button class="idea-title" data-open="${i.id}">${esc(i.title)}</button><p>${esc(i.summary)}</p><div class="meta">${isRecent(i)?'<span class="new">New</span>':''}<span>${esc(i.category)}</span><span>${i.model}</span><span>${esc(i.type)}</span>${i.reviewedAt?`<span>Reviewed ${esc(i.reviewedAt)}</span>`:''}</div></div><div class="evidence"><strong>${esc(i.verdict?`${i.verdict} · ${LEVEL_NAMES[i.level||'concept']}`:i.evidence)}</strong>${esc(i.status)}</div><button class="bookmark ${saved.has(i.id)?'saved':''}" data-save="${i.id}" aria-label="${saved.has(i.id)?'Remove':'Save'} ${esc(i.name)}" aria-pressed="${saved.has(i.id)}">${bookmarkIcon}</button></article>`).join(''):`<div class="empty"><h3>${view==='saved'&&!saved.size?'Your next idea belongs here.':'No ideas match these filters.'}</h3><p>${view==='saved'&&!saved.size?'Save an idea from the collection to build your shortlist.':'Try a different search or reset your filters.'}</p><button class="quiet" id="reset">${view==='saved'&&!saved.size?'Explore the collection':'Reset filters'}</button></div>`}
function toggleSave(id){if(saved.has(id))saved.delete(id);else saved.add(id);persist();render();const b=$('#report [data-save]');if(b){b.textContent=saved.has(id)?'Saved to shortlist':'Save to shortlist';b.setAttribute('aria-pressed',saved.has(id))}toast(saved.has(id)?'Added to your shortlist':'Removed from your shortlist')}
function openReport(id){const i=IDEAS.find(x=>x.id===id);if(!i){location.hash='';return}$('#library').hidden=true;$('#report').hidden=false;document.title=`${i.name} — Fieldnotes`;const section=(title,body)=>`<section><h2>${title}</h2>${body}</section>`;$('#report').innerHTML=`<button class="back" id="back">← Back to ${view==='saved'?'your shortlist':'the collection'}</button><div class="report-header"><div class="meta"><span>${esc(i.category)}</span><span>${i.model}</span><span>${esc(i.type)}</span></div><h1 tabindex="-1">${esc(i.title)}</h1><p>${esc(i.summary)}</p><div class="report-actions"><button class="primary" data-save="${i.id}" aria-pressed="${saved.has(i.id)}">${saved.has(i.id)?'Saved to shortlist':'Save to shortlist'}</button><button class="quiet" id="copy-link">Copy idea link</button></div></div><div class="report-layout"><article class="report-body"><div class="disclaimer">${i.evidenceLog?.length?`Researched report, reviewed ${esc(i.reviewedAt)}. ${esc(i.sourceNote)} Strongest evidence: ${LEVEL_NAMES[i.level||'concept']}. Claims without a linked source are listed as assumptions.`:'Original concept brief. Customer demand, pricing, market size, and competitive advantage have not been independently validated. Use this as a starting hypothesis, not a market report.'}</div>${i.verdict?section(`Verdict: ${esc(i.verdict)}`,`<p>${esc(i.verdictRationale)}</p><p class="next-step"><strong>Next step:</strong> ${esc(i.nextStep)}</p>`):''}${section('The problem',`<p>${esc(i.problem)}</p>`)}${section('Who would buy it',`<p>${esc(i.buyer)}</p>`)}${section('What to build first',`<p>${esc(i.solution)}</p>`)}${section('How it could make money',`<p>${esc(i.revenue)}</p>`)}${section('The opening in the market',`<p>${esc(i.gap)}</p>`)}${section('What makes the timing plausible',`<p>${esc(i.timing)}</p>`)}${section('What could break the idea',`<ul>${i.risks.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`)}${section('Your first validation sprint',`<ol>${i.pilot.map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`)}${i.fit?section('Fit for the builder',`<p>${esc(i.fit)}</p>`):''}${i.assumptions?.length?section('Assumptions still to test',`<ul>${i.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`):''}${i.evidenceLog?.length?section('Evidence log',`<p>${esc(i.sourceNote)}</p><ol class="evidence-log">${i.evidenceLog.map(e=>`<li><p>${esc(e.observation)}</p><div class="meta"><span>${esc(LEVEL_NAMES[e.level]||e.level)}</span><span>${esc(e.sourceType)}</span><span>${e.publishedAt?`Published ${esc(e.publishedAt)}`:'Publish date unknown'}</span><span>Checked ${esc(e.observedAt)}</span></div><dl><dt>Supports</dt><dd>${esc(e.supports)}</dd><dt>Limits</dt><dd>${esc(e.limitations)}</dd></dl><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.label)} ↗</a></li>`).join('')}</ol>`):i.sources?section('Evidence and further reading',`<p>${esc(i.sourceNote)}</p><ul class="sources">${i.sources.map(([name,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a></li>`).join('')}</ul>`):''}</article><aside class="report-aside"><h3>At a glance</h3><div class="fact"><span>CONCEPT</span><p>${esc(i.name)}</p></div><div class="fact"><span>BUSINESS MODEL</span><p>${esc(i.type)}</p></div><div class="fact"><span>BUYER</span><p>${i.model==='B2B'?'Business customer':'Individual / household'}</p></div><div class="fact"><span>VERDICT</span><p>${esc(i.verdict||'Validate before building')}</p></div><div class="fact"><span>STRONGEST EVIDENCE</span><p>${LEVEL_NAMES[i.level||'concept']}</p></div>${i.reviewedAt?`<div class="fact"><span>REVIEWED</span><p>${esc(i.reviewedAt)}</p></div>`:''}<label class="note-label">Your working notes<small>Saved in this browser. Export for a backup.</small><textarea id="notes" placeholder="What would you test? Who could you interview?">${esc(notes[i.id]||'')}</textarea></label><div class="notes-status" aria-live="polite"></div></aside></div>`;$('#notes').addEventListener('input',e=>{notes[i.id]=e.target.value;const ok=persist();$('.notes-status').textContent=ok?'Notes saved in this browser':'Not saved. Use Export notes.'});window.scrollTo(0,0);$('#report h1').focus({preventScroll:true})}
function route(){const id=location.hash.slice(1);if(id)openReport(id);else{$('#report').hidden=true;$('#library').hidden=false;document.title='Fieldnotes — An idea worth exploring';render()}}
function reset(){category='All';$('#search').value='';$('#model').value='all';$('#evidence').value='all';$('#verdict').value='all';$('#sort').value='default'}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){location.hash=b.dataset.open;return}if(b.dataset.save){toggleSave(b.dataset.save);return}if(b.dataset.category){category=b.dataset.category;render();return}if(b.id==='browse'||b.id==='saved'){view=b.id==='saved'?'saved':'explore';reset();location.hash='';route();return}if(b.id==='back'){location.hash='';return}if(b.id==='reset'){if(view==='saved'&&!saved.size)view='explore';reset();render();return}if(b.id==='copy-link'){try{await navigator.clipboard.writeText(location.href);toast('Idea link copied')}catch{toast('Copy the address from your browser to share this idea.')}return}if(b.id==='export'){const content=JSON.stringify({exportedAt:new Date().toISOString(),shortlist:IDEAS.filter(i=>saved.has(i.id)).map(i=>({id:i.id,name:i.name,title:i.title})),notes},null,2);const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='fieldnotes-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your shortlist and notes exported');return}if(b.id==='import'){$('#import-file').click()}});
async function importBackup(file){let data;try{data=JSON.parse(await file.text())}catch{toast('That file is not a Fieldnotes backup.');return}if(!data||typeof data!=='object'||!Array.isArray(data.shortlist)||!data.notes||typeof data.notes!=='object'||Array.isArray(data.notes)){toast('That file is not a Fieldnotes backup.');return}const known=new Set(IDEAS.map(i=>i.id));let added=0,merged=0;for(const item of data.shortlist)if(known.has(item?.id)&&!saved.has(item.id)){saved.add(item.id);added++}for(const[id,note]of Object.entries(data.notes)){if(!known.has(id)||typeof note!=='string'||!note.trim())continue;const local=notes[id]||'';if(local===note||local.includes(note))continue;notes[id]=local.trim()?`${local}\n\n— Imported —\n${note}`:note;merged++}persist();route();toast(`Imported ${added} shortlisted ${added===1?'idea':'ideas'} and ${merged} ${merged===1?'note':'notes'}.`)}
$('#import-file').addEventListener('change',e=>{const f=e.target.files[0];e.target.value='';if(f)importBackup(f)});
$('#search').addEventListener('input',render);$('#model').addEventListener('change',render);$('#sort').addEventListener('change',render);$('#evidence').addEventListener('change',render);$('#verdict').addEventListener('change',render);window.addEventListener('hashchange',route);route();
